/**
 * ============================================================
 *  SandDrop — Suspicious User Removal Script
 *  Removes 505 flagged wallet addresses from Firebase RTDB
 * ============================================================
 *
 *  PREREQUISITES
 *  -------------
 *  1. Node.js v18+  →  https://nodejs.org
 *     Verify:  node -v
 *
 *  2. Install the Firebase Admin SDK:
 *     npm install firebase-admin
 *
 *  3. Generate a Service Account Key:
 *     Firebase Console → Project Settings → Service Accounts
 *     → "Generate new private key" → save as serviceAccountKey.json
 *     → place it in the SAME folder as this script
 *
 *  4. (Optional) Backup your database first:
 *     Firebase Console → Realtime Database → ⋮ → Export JSON
 *
 *  HOW TO RUN
 *  ----------
 *     node remove_suspicious_users.js
 *
 *  WHAT IT DOES
 *  ------------
 *  Sends ONE atomic multi-path update to Firebase that sets
 *  every suspicious wallet path to null (= delete in RTDB).
 *  All 505 deletions happen in a single network request.
 * ============================================================
 */

const admin = require("firebase-admin");
const serviceAccount = require("./serviceAccountKey.json");

// CONFIG
const DATABASE_URL =
  "https://sanddrop-32496-default-rtdb.asia-southeast1.firebasedatabase.app";
const LEADERBOARD_PATH = "leaderboards/SandDrop";

admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
  databaseURL: DATABASE_URL,
});

const db = admin.database();

