// Merge arrays
const SUSPICIOUS_WALLETS = [
  ...burst_wallets.trim().split("\n"),
].map(w => w.trim()).filter(w => w.length > 0); // clean up empty lines

async function removeSuspiciousUsers() {
  console.log("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
  console.log(" SandDrop — Suspicious User Removal");
  console.log("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
  console.log(`Target:   ${DATABASE_URL}`);
  console.log(`Path:     ${LEADERBOARD_PATH}`);
  console.log(`Accounts: ${SUSPICIOUS_WALLETS.length}`);
  console.log("───────────────────────────────────────────────");

  const updates = {};
  for (const wallet of SUSPICIOUS_WALLETS) {
    updates[`${LEADERBOARD_PATH}/${wallet.trim()}`] = null;
  }

  console.log("Sending atomic delete request to Firebase...");
  try {
    await db.ref("/").update(updates);
    console.log(`✅ Done! ${SUSPICIOUS_WALLETS.length} accounts removed successfully.`);
  } catch (err) {
    console.error("❌ Error during deletion:", err.message);
    process.exit(1);
  } finally {
    await admin.app().delete(); // ✅ Fixed from [admin.app](http://admin.app)()
  }
}

removeSuspiciousUsers();